    const key = found.position;
    const runs = Number(row.runs || 0);
    const balls = Number(row.balls || 0);
    const boundaries = Number(row.boundaries || 0);
    const wickets = Number(row.wickets || 0);
    const dots = Number(row.dots || 0);
